SELECT 


    o.price_alert = #{priceAlert}
    AND o.supplier_id = #{supplierId}

        AND (m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%')
             OR o.title LIKE CONCAT('%', #{keyword}, '%') OR o.offer_id = #{keyword}
             OR o.seller_login_id LIKE CONCAT('%', #{keyword}, '%') OR o.seller_name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY o.price_alert DESC, o.id DESC
